    questions: [
      { q: 'Where should the shelf go?', options: ['auf den Tisch', 'an die Wand, neben das Fenster', 'in den Keller', 'unter das Fenster'], answer: 1,
        explain: '"Stell das Regal bitte an die Wand, neben das Fenster." \u2014 direction \u2192 Akkusativ.' },
      { q: 'What happens to the books?', options: ['sie liegen jetzt auf dem Regal', 'sie stehen im Schrank', 'sie h\u00e4ngen an der Wand', 'sie stecken in der Tasche'], answer: 0,
        explain: '"Leg sie auf das Regal." \u2192 "sie liegen jetzt oben."' },
      { q: 'Where is the key at first?', options: ['in der Schublade', 'in der Tasche', 'auf dem Tisch', 'am Fenster'], answer: 1,
        explain: '"Er steckt in der Tasche, wie immer." \u2014 position \u2192 Dativ.' },
      { q: 'Where does the picture hang now?', options: ['an der T\u00fcr', '\u00fcber dem Sofa', 'neben dem Fenster', 'hinter dem Regal'], answer: 1,
        explain: '"\u2026 jetzt h\u00e4ngt es genau \u00fcber dem Sofa." \u2014 position \u2192 Dativ.' }
    ]
